public func enumerateVisibleItems(reversed: Bool = false, inset: CGFloat = 0, with callback:(TableRowItem)->Bool) {
    let visible = visibleRows(inset)
    if reversed {
        for i in stride(from: visible.location + visible.length - 1, to: visible.location - 1, by: -1) {
            if !callback(list[i]) {
                break
            }
        }
    } else {
        for i in visible.location ..< visible.location + visible.length  {
            if !callback(list[i]) {
                break
            }
        }
    }

}

public func enumerateVisibleItems(reversed: Bool = false, inset: CGFloat = 0, with callback: (TableRowItem) -> Bool) {
    let visible = visibleRows(inset)
    let count = list.count
    guard visible.length > 0, visible.location >= 0, visible.location < count else { return }
    let end = visible.location + min(visible.length, count - visible.location)
    var rowStateVersion = self.rowStateVersion
    if reversed {
        for index in (visible.location..<end).reversed() {
            if self.rowStateVersion != rowStateVersion {
                guard index < list.count else { break }
                rowStateVersion = self.rowStateVersion
            }
            if !callback(list[index]) { break }
        }
    } else {
        var index = visible.location
        var currentEnd = end
        while true {
            if self.rowStateVersion != rowStateVersion {
                currentEnd = min(end, list.count)
                rowStateVersion = self.rowStateVersion
            }
            guard index < currentEnd else { break }
            if !callback(list[index]) { break }
            index += 1
        }
    }
}

public func optionalItem(at:Int) -> TableRowItem? {
    return at < count && at >= 0 ? self.item(at: at) : nil
}

public func optionalItem(at: Int) -> TableRowItem? {
    guard at >= 0 else { return nil }
    let items = list
    return at < items.count ? items[at] : nil
}
